package mdm

import (
	"fmt"
	"io"
	"text/template"

	"github.com/meetflowstate/flowstate-telemetry/internal/config"
)

const jamfTemplate = `#!/bin/bash
# Flowstate Telemetry — Jamf Pro deployment script
# Generated by flowstate-telemetry generate-mdm --format jamf
# Deploy via Jamf Pro > Policies > Scripts
#
# KEY: this script embeds ONE Flowstate key. Every user it configures is
# attributed to that key's owner in Flowstate. For per-user attribution give
# each user their own key: pass it as script parameter 4 (for example from a
# per-user extension attribute), which overrides the embedded key.
#
# The key is never exported as OTEL_EXPORTER_OTLP_HEADERS (every OpenTelemetry
# SDK would send it to its own collector). It goes only into each user's tool
# settings and ~/.config/flowstate-telemetry/env (mode 0600), which the
# Cursor/Windsurf/Antigravity hook scripts read.
set -euo pipefail

ENDPOINT="{{ .Endpoint }}"
KEY="${4:-{{ .Key }}}"

echo "==> Configuring Flowstate telemetry for all users..."

# Remove what earlier versions installed: a world-readable
# /etc/flowstate-telemetry.env and a LaunchDaemon/LaunchAgent that published
# the key (and OTEL_EXPORTER_OTLP_HEADERS) to every app in the session.
rm -f /etc/flowstate-telemetry.env
if [ -f /Library/LaunchDaemons/inc.flowstate.telemetry.env.plist ]; then
    launchctl bootout system/inc.flowstate.telemetry.env 2>/dev/null || true
    rm -f /Library/LaunchDaemons/inc.flowstate.telemetry.env.plist
fi
rm -f /Library/LaunchAgents/inc.flowstate.telemetry.env.plist
CONSOLE_USER=$(stat -f %Su /dev/console 2>/dev/null || true)
if [ -n "$CONSOLE_USER" ] && [ "$CONSOLE_USER" != "root" ]; then
    CONSOLE_UID=$(id -u "$CONSOLE_USER" 2>/dev/null || true)
    if [ -n "$CONSOLE_UID" ]; then
        for VAR in OTEL_EXPORTER_OTLP_HEADERS FLOWSTATE_OTLP_KEY FLOWSTATE_OTLP_ENDPOINT; do
            launchctl asuser "$CONSOLE_UID" sudo -u "$CONSOLE_USER" launchctl unsetenv "$VAR" 2>/dev/null || true
        done
    fi
fi

# Configure Claude Code for each user
for HOMEDIR in /Users/*; do
    [ -d "$HOMEDIR" ] || continue
    USERNAME=$(basename "$HOMEDIR")
    [ "$USERNAME" = "Shared" ] && continue

    # Claude Code settings
    CLAUDE_DIR="$HOMEDIR/.claude"
    mkdir -p "$CLAUDE_DIR"
    SETTINGS="$CLAUDE_DIR/settings.json"

    if [ -f "$SETTINGS" ]; then
        # Merge with existing settings using Python (available on macOS)
        python3 -c "
import json, sys
with open('$SETTINGS') as f:
    s = json.load(f)
env = s.setdefault('env', {})
env.pop('OTEL_METRICS_TEMPORALITY_PREFERENCE', None)
env.update({
    'CLAUDE_CODE_ENABLE_TELEMETRY': '1',
    'OTEL_METRICS_EXPORTER': 'otlp',
    'OTEL_LOGS_EXPORTER': 'otlp',
    'OTEL_EXPORTER_OTLP_PROTOCOL': 'http/protobuf',
    'OTEL_EXPORTER_OTLP_ENDPOINT': '$ENDPOINT',
    'OTEL_EXPORTER_OTLP_HEADERS': 'x-flowstate-key=$KEY',
    'OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE': 'delta',
    'OTEL_METRICS_INCLUDE_SESSION_ID': 'true',
    'OTEL_METRICS_INCLUDE_ACCOUNT_UUID': 'true'
})
with open('$SETTINGS', 'w') as f:
    json.dump(s, f, indent=2)
"
    else
        cat > "$SETTINGS" <<CLAUDEEOF
{
  "env": {
    "CLAUDE_CODE_ENABLE_TELEMETRY": "1",
    "OTEL_METRICS_EXPORTER": "otlp",
    "OTEL_LOGS_EXPORTER": "otlp",
    "OTEL_EXPORTER_OTLP_PROTOCOL": "http/protobuf",
    "OTEL_EXPORTER_OTLP_ENDPOINT": "$ENDPOINT",
    "OTEL_EXPORTER_OTLP_HEADERS": "x-flowstate-key=$KEY",
    "OTEL_EXPORTER_OTLP_METRICS_TEMPORALITY_PREFERENCE": "delta",
    "OTEL_METRICS_INCLUDE_SESSION_ID": "true",
    "OTEL_METRICS_INCLUDE_ACCOUNT_UUID": "true"
  }
}
CLAUDEEOF
    fi
    chown "$USERNAME" "$SETTINGS" "$CLAUDE_DIR"

    # Endpoint and key for hook scripts (editors launched from the Dock do
    # not read shell profiles). Readable by this user only.
    if [ ! -d "$HOMEDIR/.config" ]; then
        mkdir "$HOMEDIR/.config"
        chown "$USERNAME" "$HOMEDIR/.config"
    fi
    CONF_DIR="$HOMEDIR/.config/flowstate-telemetry"
    mkdir -p "$CONF_DIR"
    chmod 700 "$CONF_DIR"
    (umask 077; printf 'FLOWSTATE_OTLP_ENDPOINT=%s\nFLOWSTATE_OTLP_KEY=%s\n' "$ENDPOINT" "$KEY" > "$CONF_DIR/env")
    chown -R "$USERNAME" "$CONF_DIR"

    # Cursor hooks
    CURSOR_DIR="$HOMEDIR/.cursor"
    if [ -d "$CURSOR_DIR" ] || [ -d "/Applications/Cursor.app" ]; then
        mkdir -p "$CURSOR_DIR/hooks"
        # Hook script would be deployed separately or embedded here
        chown -R "$USERNAME" "$CURSOR_DIR"
    fi

    echo "  Configured: $USERNAME"
done

echo "==> Flowstate telemetry configuration complete."
exit 0
`

// GenerateJamf writes a Jamf Pro deployment script to the given writer.
func GenerateJamf(w io.Writer, cfg config.Config) error {
	tmpl, err := template.New("jamf").Parse(jamfTemplate)
	if err != nil {
		return fmt.Errorf("parsing template: %w", err)
	}

	return tmpl.Execute(w, map[string]string{
		"Endpoint": cfg.Endpoint,
		"Key":      cfg.Key,
	})
}
